fn fibonacci(n: usize) -> Vec<i32> {
    // n is at least 2 per the problem statement
    let mut result = Vec::with_capacity(n);
    
    // Push the first two Fibonacci numbers
    result.push(0);
    result.push(1);
    
    // Generate the remaining numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}